def workspace():
    cfg = tomllib.loads((ROOT / "mono.toml").read_text())
    return cfg["workspace"]["members"], ROOT / cfg.get("index", {}).get("path", "vendor")


def member_deps(member):
    project = tomllib.loads((ROOT / member / "pyproject.toml").read_text())["project"]
    deps = {}
    for raw in project.get("dependencies", []):
        name, rest = SPEC.match(raw).groups()
        deps[name] = [OP.match(c.strip()).groups() for c in rest.split(",") if c.strip()]
    return project["name"], deps


def available(index, name):
    return sorted((vtuple(p.name[len(name) + 1:]) for p in index.glob(f"{name}-*") if p.is_dir()), reverse=True)


def satisfies(version, constraints):
    checks = {">=": lambda a, b: a >= b, "<=": lambda a, b: a <= b, "==": lambda a, b: a == b,
              "<": lambda a, b: a < b, ">": lambda a, b: a > b}
    return all(checks[op](version, vtuple(v)) for op, v in constraints)


def owners(path):
    found = []
    for line in (ROOT / "CODEOWNERS").read_text().splitlines():
        if line.strip() and not line.startswith("#"):
            pattern, *who = line.split()
            if str(path).startswith(pattern.strip("/")):
                found = who
    return found


def resolve():
    members, index = workspace()
    wanted = {}
    for member in members:
        name, deps = member_deps(member)
        for dep, constraints in deps.items():
            wanted.setdefault(dep, []).append((member, name, constraints))
    locked, conflicts = {}, []
    for dep, users in sorted(wanted.items()):
        options = [v for v in available(index, dep) if all(satisfies(v, c) for _, _, c in users)]
        if options:
            locked[dep] = ".".join(map(str, options[0]))
            continue
        lines = [f"  {name} ({member}/pyproject.toml, owners: {' '.join(owners(member)) or '-'}) requires "
                 + ",".join(op + v for op, v in c) for member, name, c in users]
        conflicts.append(f"resolution conflict: no vendored {dep} satisfies every member\n" + "\n".join(lines))
    return locked, conflicts


def read_lock():
    lock = ROOT / "mono.lock"
    return tomllib.loads(lock.read_text()).get("resolved", {}) if lock.exists() else {}


def cmd_check(args):
    locked, conflicts = resolve()
    if conflicts:
        print("\n".join(conflicts), file=sys.stderr)
        print("mono.lock left unchanged", file=sys.stderr)
        return 1
    body = "".join(f'{dep} = "{ver}"\n' for dep, ver in sorted(locked.items()))
    (ROOT / "mono.lock").write_text("# generated by ./mono check - do not edit\n[resolved]\n" + body)
    print("workspace resolves: " + ", ".join(f"{d} {v}" for d, v in sorted(locked.items())))
    return 0


